sys_ui_page.client_script:
function updateIncidents() {
    var selectedIncidents = [];
    var checkboxes = document.querySelectorAll('.incident-checkbox:checked');
    checkboxes.forEach(function(checkbox) {
        selectedIncidents.push(checkbox.value);
    });

    if (selectedIncidents.length === 0) {
        alert('Please select at least one incident to update.');
        return;
    }

    var comments = document.getElementById('commentsInput').value;
    if (!comments.trim()) {
        alert('Please enter comments to update.');
        return;
    }

    var ga = new GlideAjax('x_938076_now_utils.OptionProcessorAjax');
    ga.addParam('sysparm_name', 'updateIncidentComments');
    ga.addParam('sysparm_incident_sys_ids', selectedIncidents.join(','));
    ga.addParam('sysparm_comments', comments);
    ga.getXML(function(response) {
        var answer = response.responseXML.documentElement.getAttribute('answer');
        if (answer === 'success') {
            alert('Incidents updated successfully!');
            refreshIncidentList(); // Re-run filter/search to show updated comments
            document.getElementById('commentsInput').value = ''; // Clear comments box
            document.getElementById('selectAll').checked = false; // Uncheck select all
        } else {
            alert('Error updating incidents: ' + answer);
        }
    });
}

function searchIncidents() {
    // Clear any active encoded query when performing a keyword search
    document.getElementById('encodedQueryInput').value = '';
    refreshIncidentList();
}

function applyEncodedQuery() {
    // Clear any active keyword search when applying an encoded query
    document.getElementById('searchInput').value = '';
    refreshIncidentList();
}

function refreshIncidentList() {
    var searchKeyword = document.getElementById('searchInput').value;
    var encodedQuery = document.getElementById('encodedQueryInput').value;

    var ga = new GlideAjax('x_938076_now_utils.OptionProcessorAjax');
    ga.addParam('sysparm_name', 'getFilteredIncidents');
    ga.addParam('sysparm_keyword', searchKeyword);
    ga.addParam('sysparm_encoded_query', encodedQuery);
    ga.getXML(function(response) {
        var incidents = JSON.parse(response.responseXML.documentElement.getAttribute('answer'));
        var tableBody = document.getElementById('incidentTableBody');
        tableBody.innerHTML = ''; // Clear existing list
        var noIncidentsMessage = document.getElementById('noIncidentsMessage');

        if (incidents.length > 0) {
            incidents.forEach(function(incident) {
                var row = tableBody.insertRow();
                row.setAttribute('data-sysid', incident.sys_id);

                var checkboxCell = row.insertCell();
                checkboxCell.innerHTML = '<input type="checkbox" class="incident-checkbox" value="' + incident.sys_id + '"/>';

                var numberCell = row.insertCell();
                numberCell.innerHTML = '<a href="incident.do?sys_id=' + incident.sys_id + '" target="_blank">' + incident.number + '</a>';

                var shortDescriptionCell = row.insertCell();
                shortDescriptionCell.innerText = incident.short_description;

                var stateCell = row.insertCell();
                stateCell.innerText = incident.state;

                var commentsCell = row.insertCell();
                commentsCell.innerText = incident.comments;
            });
            noIncidentsMessage.style.display = 'none';
        } else {
            noIncidentsMessage.style.display = 'block';
        }
        document.getElementById('selectAll').checked = false;
    });
}

function clearKeywordSearchAndReload() {
    document.getElementById('searchInput').value = '';
    refreshIncidentList();
}

function clearEncodedQueryAndReload() {
    document.getElementById('encodedQueryInput').value = '';
    refreshIncidentList();
}

// Function to open the native filter builder for the Incident table
function openNativeFilterBuilder() {
    var queryInput = document.getElementById('encodedQueryInput');
    var tableName = 'incident';

    var g_filter_builder = new GwtFilterBuilder(tableName, queryInput.id);
    g_filter_builder.setReadOnly(false);
    g_filter_builder.showDialog();

    // Use a MutationObserver to automatically apply the filter when the input's value changes
    // This makes the "Build Query" experience more seamless.
    var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(mutation) {
            if (mutation.type === 'attributes' && mutation.attributeName === 'value') {
                // Input value has changed, likely from the filter builder
                // Disconnect observer to prevent infinite loops or multiple calls
                observer.disconnect();
                // Automatically apply the filter
                applyEncodedQuery();
            }
        });
    });

    // Start observing the 'value' attribute of the encodedQueryInput
    observer.observe(queryInput, { attributes: true });
}


function toggleAllCheckboxes(source) {
    var checkboxes = document.querySelectorAll('.incident-checkbox');
    checkboxes.forEach(function(checkbox) {
        checkbox.checked = source.checked;
    });
}

// Initial load of incidents when the page loads
addLoadEvent(function() {
    refreshIncidentList();
});
